public enum RefusalCode: Codable, Hashable, Sendable {
    case notFound
    case changed
    case argsChanged
    case replyWaiting
    case notPermitted
    case unsupported
    /// A value this build does not know (sent by a newer Watchtower).
    case unknown(String)

    public init(rawValue: String) {
        switch rawValue {
        case "not_found": self = .notFound
        case "changed": self = .changed
        case "args_changed": self = .argsChanged
        case "reply_waiting": self = .replyWaiting
        case "not_permitted": self = .notPermitted
        case "unsupported": self = .unsupported
        default: self = .unknown(rawValue)
        }
    }

    public var rawValue: String {
        switch self {
        case .notFound: "not_found"
        case .changed: "changed"
        case .argsChanged: "args_changed"
        case .replyWaiting: "reply_waiting"
        case .notPermitted: "not_permitted"
        case .unsupported: "unsupported"
        case .unknown(let value): value
        }
    }

    public init(from decoder: Decoder) throws {
        self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
    }

    public func encode(to encoder: Encoder) throws {
        var container = encoder.singleValueContainer()
        try container.encode(rawValue)
    }

    public static func == (lhs: Self, rhs: Self) -> Bool {
        lhs.rawValue == rhs.rawValue
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(rawValue)
    }
}

